use Carbon\CarbonImmutable as Time;
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{Artisan,DB,Crypt,Http,Mail};
use Illuminate\Support\Str;
final class CommercialToolsTest extends TestCase
{
 private string $path;
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();if(config('database.default')!=='sqlite'&&!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Külön tesztadatbázis szükséges.');Artisan::call('migrate',['--force'=>true]);Time::setTestNow('2036-05-06T08:00:00Z');$this->path=storage_path('framework/commercial-'.bin2hex(random_bytes(6)));config(['integrations.path'=>$this->path,'operator.connections_path'=>$this->path.'-platform','integrations.sms_segment_price'=>25]);foreach(['sms_ledger','sms_reservations','sms_wallets','sms_topups','marketing_connections','marketing_campaigns','marketing_consents','newsletter_consents','deliveries','calendar_tasks','calendar_connections','providers','provider_members','provider_security','guest_invitations','platform_payments','platform_messages','salon_state','guest_accounts'] as $table)DB::table($table)->delete();foreach([1,2] as $id)DB::table('salon_state')->insert(['id'=>$id,'data'=>json_encode(SalonStore::initial())]);DB::table('providers')->insert(['id'=>2,'name'=>'Other','email'=>'other@example.com','password_hash'=>'test','active'=>true,'trial_started_at'=>now(),'trial_ends_at'=>now()->addYear(),'created_at'=>now(),'updated_at'=>now()]);$this->admin();Http::preventStrayRequests();Mail::fake();}
 protected function tearDown():void{Time::setTestNow();foreach(glob($this->path.'*') as $f)if(is_file($f))unlink($f);parent::tearDown();}
 private function admin():void{$this->withSession(['admin'=>true,'provider_id'=>1,'_token'=>str_repeat('c',40)])->withHeader('X-CSRF-TOKEN',str_repeat('c',40));}
 private function smsJobs(int $count=10):int{
  app(PlatformConnections::class)->save(['bulkgate_application_id'=>'12345','bulkgate_application_token'=>'fake-bulkgate-secret','bulkgate_sender_type'=>'gSystem']);$bookings=[];for($i=0;$i<$count;$i++)$bookings[]=['id'=>'b'.$i,'name'=>'Vendég '.$i,'phone'=>'06301234567','email'=>'','staff'=>'anna','services'=>['cut'],'status'=>'confirmed','start'=>now()->addDay()->toISOString(),'serviceSnapshot'=>[['name'=>'Hajvágás','price'=>8500,'duration'=>45]],'token'=>str_repeat((string)($i%9),48),'updatedAt'=>now()->toISOString()];
  app(SalonStore::class)->mutate(function(&$s)use($bookings){$s['bookings']=$bookings;$s['settings']['notifyGuest']=true;$s['settings']['channel']='sms';$s['settings']['reminderGuest']=false;},false);$state=app(SalonStore::class)->read();foreach($bookings as $b)app(Notifications::class)->enqueue($b,$state,'created');$first=DB::table('deliveries')->first();$p=json_decode(Crypt::decryptString($first->payload),true);return SmsWallet::segments(app(Notifications::class)->smsContent($p,$state)['text'])*25;
 }
 private function acceptedSms():void{$i=0;Http::fake(['portal.bulkgate.com/*'=>function()use(&$i){return Http::response(['data'=>['status'=>'accepted','sms_id'=>'sms-'.++$i]]);}]);}
 private function stripeEvent(array $object,string $type='checkout.session.completed'){
  config(['integrations.platform_stripe.webhook_secret'=>'central-signature-secret']);$body=json_encode(['id'=>'evt-'.Str::uuid(),'type'=>$type,'created'=>time(),'data'=>['object'=>$object]]);$t=time();return $this->call('POST','/api/platform-stripe/webhook',[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_STRIPE_SIGNATURE'=>'t='.$t.',v1='.hash_hmac('sha256',$t.'.'.$body,'central-signature-secret')],$body);
 }
 private function marketingKeys(string $engine='brevo'):array{return ['engine'=>$engine,'apiKey'=>$engine==='brevo'?'fake-brevo-secret':'fake-mailchimp-us21','senderEmail'=>'sender@example.com','senderName'=>'Szalon','company'=>'Szalon','address'=>'Utca 1.','city'=>'Adony','zip'=>'2457','country'=>'HU'];}
 private function pro():void{app(SalonStore::class)->mutate(function(&$s){$s['subscription']=['plan'=>'pro','status'=>'active'];});}
 public function test_ten_sms_with_only_five_worth_of_funds_send_none_and_create_one_internal_alert():void{
  $price=$this->smsJobs();SmsWallet::credit(1,$price*5,'opening');$this->acceptedSms();$r=app(Notifications::class)->run(2,1);$this->assertSame(0,$r['sent']);$this->assertSame(10,DB::table('deliveries')->where('status','waiting_balance')->count());$this->assertSame(0,DB::table('sms_reservations')->count());$this->assertSame(1,DB::table('platform_messages')->count());app(Notifications::class)->run(20,1);$this->assertSame(1,DB::table('platform_messages')->count());$this->assertSame($price*5,SmsWallet::info(1)['available']);Http::assertNothingSent();
 }
 public function test_full_batch_is_reserved_even_when_worker_limit_is_two_and_is_never_charged_twice():void{
  $price=$this->smsJobs();SmsWallet::credit(1,$price*10,'opening');$this->acceptedSms();$r=app(Notifications::class)->run(2,1);$this->assertSame(2,$r['sent']);$this->assertSame($price*8,SmsWallet::info(1)['reserved']);$this->assertSame(0,SmsWallet::info(1)['available']);$this->assertSame(10,DB::table('sms_reservations')->count());app(Notifications::class)->run(20,1);app(Notifications::class)->run(20,1);Http::assertSentCount(10);$this->assertSame(0,SmsWallet::info(1)['balance']);$this->assertSame(0,SmsWallet::info(1)['reserved']);$this->assertSame(-$price*10,(int)DB::table('sms_ledger')->where('kind','sms')->sum('amount'));
 }
 public function test_funded_batch_keeps_its_price_and_insufficient_other_provider_cannot_spend_it():void{
  $price=$this->smsJobs(2);SmsWallet::credit(1,$price*2,'opening');SmsWallet::prepare(1);config(['integrations.sms_segment_price'=>30]);$this->acceptedSms();app(Notifications::class)->run(20,1);$this->assertSame(25,(int)DB::table('sms_reservations')->value('unit_price'));$this->assertSame(0,SmsWallet::info(1)['balance']);$this->assertSame(0,SmsWallet::info(2)['available']);$this->withSession(['provider_id'=>2]);$this->getJson('/api/sms-wallet?provider=1')->assertForbidden();
 }
 public function test_timeout_keeps_funds_reserved_until_explicit_resolution():void{
  $price=$this->smsJobs(1);SmsWallet::credit(1,$price,'opening');Http::fake(fn()=>throw new \Illuminate\Http\Client\ConnectionException('secret must not leak'));app(Notifications::class)->run(1,1);$job=DB::table('deliveries')->first();$this->assertSame('unknown',$job->status);$this->assertSame($price,SmsWallet::info(1)['reserved']);$this->assertSame($price,SmsWallet::info(1)['balance']);$this->postJson('/api/sms-wallet/deliveries/'.$job->id.'/resolve',['result'=>'not_sent','confirmed'=>true])->assertOk();$this->assertSame($price,SmsWallet::info(1)['available']);$this->assertSame(0,SmsWallet::info(1)['reserved']);
 }
 public function test_topup_is_credited_only_by_valid_matching_paid_webhook_and_refund_is_cumulative():void{
  config(['integrations.platform_stripe.key'=>'fake-stripe-key']);Http::fake(['api.stripe.com/v1/checkout/sessions'=>Http::response(['id'=>'cs_wallet','url'=>'https://checkout.stripe.com/c/pay/test'])]);$request=(string)Str::uuid();$this->postJson('/api/sms-wallet',['amount'=>3000,'requestId'=>$request,'acceptPrice'=>true])->assertOk();$this->postJson('/api/sms-wallet',['amount'=>3000,'requestId'=>$request,'acceptPrice'=>true])->assertOk();Http::assertSentCount(1);$this->assertSame(0,SmsWallet::info(1)['balance']);$topup=DB::table('sms_topups')->first();$object=['id'=>'cs_wallet','metadata'=>['type'=>'sms_topup','provider_id'=>'1','topup_id'=>$topup->id],'currency'=>'huf','amount_total'=>300000,'payment_status'=>'paid','payment_intent'=>'pi_wallet'];$this->stripeEvent($object)->assertOk();$this->stripeEvent($object)->assertOk();$this->assertSame(3000,SmsWallet::info(1)['balance']);$refund=['payment_intent'=>'pi_wallet','amount_refunded'=>100000];$this->stripeEvent($refund,'charge.refunded')->assertOk();$this->stripeEvent($refund,'charge.refunded')->assertOk();$this->assertSame(2000,SmsWallet::info(1)['balance']);$this->stripeEvent(['payment_intent'=>'pi_wallet','amount_refunded'=>300000],'charge.refunded')->assertOk();$this->assertSame(0,SmsWallet::info(1)['balance']);$this->assertSame(0,DB::table('platform_payments')->count());
 }
 public function test_wrong_topup_amount_and_unsigned_webhook_cannot_mint_credit():void{
  config(['integrations.platform_stripe.key'=>'fake-stripe-key']);Http::fake(['api.stripe.com/*'=>Http::response(['id'=>'cs_bad','url'=>'https://checkout.stripe.com/c/pay/test'])]);$this->postJson('/api/sms-wallet',['amount'=>19,'requestId'=>(string)Str::uuid(),'acceptPrice'=>true])->assertUnprocessable();$this->postJson('/api/sms-wallet',['amount'=>3000,'requestId'=>(string)Str::uuid(),'acceptPrice'=>true])->assertOk();$topup=DB::table('sms_topups')->first();$o=['id'=>'cs_bad','metadata'=>['type'=>'sms_topup','provider_id'=>'1','topup_id'=>$topup->id],'currency'=>'huf','amount_total'=>100,'payment_status'=>'paid'];$this->stripeEvent($o)->assertUnprocessable();$this->postJson('/api/platform-stripe/webhook',['data'=>['object'=>$o]])->assertStatus(400);$this->assertSame(0,SmsWallet::info(1)['balance']);
 }
 public function test_only_first_real_subscription_payment_gives_single_500_forint_gift():void{
  $id=DB::table('platform_payments')->insertGetId(['provider_id'=>1,'reference'=>'first','amount'=>4000,'method'=>'transfer','paid_at'=>now(),'period_end'=>now()->addMonth(),'created_at'=>now(),'updated_at'=>now()]);$payment=DB::table('platform_payments')->find($id);SmsWallet::welcome($payment);SmsWallet::welcome($payment);$next=clone $payment;$next->id=$id+1;SmsWallet::welcome($next);$this->assertSame(500,SmsWallet::info(1)['balance']);$this->assertSame(1,DB::table('sms_ledger')->where('kind','gift')->count());
 }
 public function test_superadmin_controls_sms_price_and_provider_cannot_override_it():void{
  $this->putJson('/api/platform/connections',['sms_segment_price'=>30])->assertStatus(401);$this->withSession(['platform_admin'=>true]);$this->putJson('/api/platform/connections',['sms_segment_price'=>30])->assertOk();$this->assertSame(30,SmsWallet::price());$this->putJson('/api/platform/connections',['sms_segment_price'=>0])->assertUnprocessable();
 }
 public function test_marketing_is_pro_only_and_connection_keys_are_encrypted_and_preserved():void{
  app(SalonStore::class)->mutate(function(&$s){$s['subscription']=['plan'=>'basic','status'=>'active'];});$this->getJson('/api/marketing/campaigns')->assertStatus(402);$this->pro();$this->putJson('/api/marketing/connection',$this->marketingKeys())->assertOk();$this->putJson('/api/marketing/connection',array_replace($this->marketingKeys(),['apiKey'=>'']))->assertOk();$this->getJson('/api/marketing/connection')->assertOk()->assertJsonPath('configured',true)->assertJsonMissingPath('apiKey');$stored=DB::table('marketing_connections')->value('credentials');$this->assertStringNotContainsString('fake-brevo-secret',$stored);$this->assertSame('fake-brevo-secret',MarketingConnections::get(1)['apiKey']);$this->withSession(['platform_admin'=>true]);$this->putJson('/api/platform/marketing/connection',$this->marketingKeys('mailchimp'))->assertUnprocessable();$this->putJson('/api/platform/marketing/connection',$this->marketingKeys())->assertOk();$this->assertSame(2,DB::table('marketing_connections')->count());
 }
 public function test_provider_campaign_never_includes_another_salon_and_external_unsubscribe_is_respected():void{
  $this->pro();$this->putJson('/api/marketing/connection',$this->marketingKeys())->assertOk();$id=DB::table('marketing_consents')->insertGetId(['provider_id'=>1,'email'=>'own@example.com','name'=>'Saját','source'=>'Írásos hozzájárulás','consented_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('marketing_consents')->insert(['provider_id'=>2,'email'=>'other@example.com','name'=>'Másik','source'=>'Másik','consented_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$campaign=$this->postJson('/api/marketing/campaigns',['subject'=>'Próba','html'=>'<p>Levél</p><script>bad()</script>'])->assertCreated()->json('id');$this->postJson('/api/marketing/campaigns/'.$campaign.'/prepare',['recipientIds'=>[$id]])->assertOk();$record=DB::table('marketing_campaigns')->find($campaign);$this->assertStringNotContainsString('other@example.com',$record->recipients);$this->assertStringNotContainsString('<script>',$record->html);$keys=MarketingConnections::get(1);$url='/api/marketing/webhook/1/brevo/'.$keys['webhookToken'];$this->postJson($url,['event'=>'unsubscribed','email'=>'own@example.com'])->assertOk();$this->assertCount(0,MarketingCampaigns::recipients(1));$this->assertCount(1,MarketingCampaigns::recipients(2));$this->postJson('/api/marketing/webhook/1/brevo/'.str_repeat('0',64),['event'=>'unsubscribed','email'=>'other@example.com'])->assertNotFound();Http::assertNothingSent();Mail::assertNothingSent();
 }
 public function test_simplepay_signed_server_notification_is_idempotent_and_return_cannot_mark_paid():void{
  app(\App\Services\Connections::class)->save(['simplepay_merchant'=>'MERCHANT1','simplepay_secret'=>'simplepay-key','simplepay_environment'=>'sandbox']);app(SalonStore::class)->mutate(function(&$s){$s['settings']['paymentProvider']='simplepay';$s['settings']['prepaymentEnabled']=true;$s['bookings']=[['id'=>'simple-booking','staff'=>'anna','services'=>['cut'],'name'=>'Vendég','email'=>'guest@example.com','phone'=>'06301234567','status'=>'confirmed','start'=>now()->addDay()->toISOString(),'updatedAt'=>now()->toISOString(),'token'=>str_repeat('a',48),'serviceSnapshot'=>[['name'=>'Vágás','price'=>1000,'duration'=>30]]]];},false);
  Http::fake(function($r){$data=json_decode($r->body(),true);$this->assertSame(SimplePay::signature($r->body(),'simplepay-key'),$r->header('Signature')[0]);if(str_ends_with($r->url(),'/start'))$v=['transactionId'=>123,'paymentUrl'=>'https://sandbox.simplepay.hu/pay/pay/psp1?test=1'];else $v=['transactions'=>[['orderRef'=>$data['orderRefs'][0],'transactionId'=>123,'status'=>'FINISHED','currency'=>'HUF','total'=>'1000']]];$body=json_encode($v);return Http::response($body,200,['Signature'=>SimplePay::signature($body,'simplepay-key')]);});
  app(\App\Services\Payments::class)->checkout('simple-booking');$s=app(SalonStore::class)->read();$ref=array_key_first($s['checkouts']);$return=json_encode(['o'=>$ref,'m'=>'MERCHANT1','e'=>'SUCCESS']);$this->get('/simplepay/visszateres?r='.rawurlencode(base64_encode($return)).'&s='.rawurlencode(SimplePay::signature($return,'simplepay-key')))->assertRedirect();$this->assertCount(0,app(SalonStore::class)->read()['payments']);$raw=json_encode(['merchant'=>'MERCHANT1','orderRef'=>$ref,'transactionId'=>123,'status'=>'FINISHED','salt'=>'test']);for($i=0;$i<2;$i++)$this->call('POST','/api/simplepay/ipn',[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_SIGNATURE'=>SimplePay::signature($raw,'simplepay-key')],$raw)->assertOk();$this->assertCount(1,app(SalonStore::class)->read()['payments']);$this->postJson('/api/simplepay/ipn',['merchant'=>'MERCHANT1'])->assertStatus(400);
 }
 public function test_internal_messages_include_unregistered_own_client_and_cannot_be_read_by_unrelated_guest():void{
  app(SalonStore::class)->mutate(function(&$s){$s['clients']=[['id'=>'toth','name'=>'Tóth Tamás','email'=>'toth@example.com','phone'=>'06301234567']];});$this->getJson('/api/message-recipients?q=Tóth')->assertOk()->assertJsonPath('0.id','toth')->assertJsonPath('0.linked',false);$this->postJson('/api/messages',['clientId'=>'toth','text'=>'Teszt üzenet','emailCopy'=>true])->assertCreated()->assertJsonPath('readAt',null);$this->getJson('/api/messages')->assertJsonCount(1);$this->withSession(['admin'=>false,'guest_id'=>999]);$this->getJson('/api/messages')->assertExactJson([]);
 }
 public function test_both_newsletter_engines_prepare_native_campaigns_and_submit_only_once():void{
  foreach(['brevo','mailchimp'] as $engine){Http::swap(new \Illuminate\Http\Client\Factory);Http::preventStrayRequests();DB::table('marketing_campaigns')->delete();DB::table('marketing_consents')->delete();DB::table('marketing_connections')->delete();$this->pro();$this->putJson('/api/marketing/connection',$this->marketingKeys($engine))->assertOk();$id=DB::table('marketing_consents')->insertGetId(['provider_id'=>1,'email'=>'subscribed@example.com','name'=>'Feliratkozott','source'=>'Írásos beleegyezés','consented_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$calls=[];
   Http::fake(function($r)use(&$calls,$engine){$path=parse_url($r->url(),PHP_URL_PATH);$calls[]=[$r->method(),$path,$r->data()];if($r->method()==='GET'&&(str_contains($path,'/members/')||str_contains($path,'contacts/subscribed')))return Http::response([],404);if($r->method()==='GET'&&str_ends_with($path,'/lists'))return Http::response(['lists'=>[['id'=>'audience']]]);if(str_ends_with($path,'/account'))return Http::response(['plan'=>[['type'=>'free','credits'=>300]]]);if(str_ends_with($path,'/folders'))return Http::response(['id'=>7]);if(str_ends_with($path,'/lists'))return Http::response(['id'=>8]);if(str_ends_with($path,'/segments'))return Http::response(['id'=>9]);if(str_ends_with($path,'/emailCampaigns')||str_ends_with($path,'/campaigns'))return Http::response(['id'=>$engine==='brevo'?42:'campaign42']);return Http::response([],200);});
   $campaign=$this->postJson('/api/marketing/campaigns',['subject'=>'Újdonság','html'=>'<p>Szia!</p>'])->assertCreated()->json('id');$this->postJson('/api/marketing/campaigns/'.$campaign.'/prepare',['recipientIds'=>[$id]])->assertOk();$this->assertSame(1,MarketingCampaigns::run()['prepared']);$row=DB::table('marketing_campaigns')->find($campaign);$this->assertSame('ready',$row->status);$this->assertSame(0,count(array_filter($calls,fn($c)=>str_ends_with($c[1],'/sendNow')||str_ends_with($c[1],'/actions/send'))));
   $this->postJson('/api/marketing/campaigns/'.$campaign.'/test',['email'=>'owner@example.com'])->assertOk();$this->postJson('/api/marketing/campaigns/'.$campaign.'/send',['confirm'=>true])->assertOk();$this->assertSame(1,MarketingCampaigns::run()['submitted']);MarketingCampaigns::run();$this->assertSame(1,count(array_filter($calls,fn($c)=>str_ends_with($c[1],'/sendNow')||str_ends_with($c[1],'/actions/send'))));$this->postJson('/api/marketing/campaigns/'.$campaign.'/send',['confirm'=>true])->assertUnprocessable();Mail::assertNothingSent();
  }
 }
 public function test_newsletter_timeout_never_resends_and_does_not_expose_raw_error():void{
  $this->pro();MarketingConnections::save(1,$this->marketingKeys());$keys=MarketingConnections::get(1);DB::table('marketing_campaigns')->insert(['id'=>(string)Str::uuid(),'provider_id'=>1,'engine'=>'brevo','subject'=>'Próba','html'=>'<p>Próba</p>','remote_id'=>'42','status'=>'scheduled','recipients'=>json_encode(['revision'=>$keys['revision'],'items'=>[]]),'scheduled_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$calls=0;Http::fake(function($r)use(&$calls){if(str_ends_with($r->url(),'/account'))return Http::response(['plan'=>[]]);$calls++;throw new \Illuminate\Http\Client\ConnectionException('private-api-key');});$this->assertSame(1,MarketingCampaigns::run()['unknown']);MarketingCampaigns::run();$this->assertSame(1,$calls);$this->assertStringNotContainsString('private-api-key',DB::table('marketing_campaigns')->value('error'));Mail::assertNothingSent();
 }
