 public function test_manual_calendar_sync_refreshes_only_the_authenticated_staff_connection():void{
  $credentials=Crypt::encryptString(json_encode(['access_token'=>'calendar-access','refresh_token'=>'calendar-refresh','expires'=>time()+3600]));foreach(['anna','other'] as $i=>$staff)DB::table('calendar_connections')->insert(['id'=>$i+1,'owner_type'=>'staff','owner_id'=>$staff,'provider_id'=>$i+1,'credentials'=>$credentials,'calendar_id'=>'primary','enabled'=>true,'created_at'=>now(),'updated_at'=>now()]);Http::fake(['www.googleapis.com/*'=>Http::response(['items'=>[]])]);$this->postJson('/api/calendar/connection?owner=staff&staff=anna')->assertOk()->assertJsonPath('busyUpdated',1);$this->assertNotNull(DB::table('calendar_connections')->where('id',1)->value('last_synced_at'));$this->assertNull(DB::table('calendar_connections')->where('id',2)->value('last_synced_at'));$this->postJson('/api/calendar/connection?owner=staff&staff=other')->assertNotFound();Http::assertSentCount(1);
 }

